:root {
  /* === 1. 我方气泡设置 === */
  --bubble-me-bg: #2D2C31;
  --bubble-me-color: #ffffff;

  /* === 2. 对方气泡透明化 === */
  --bubble-them-bg: transparent;
  --bubble-them-color: #333333;
  --bubble-them-border: none;
  --bubble-them-shadow: none;

  /* === 3. 气泡整体等比缩小 === */
  /* 通过缩小字号和常规内边距来实现等比例变小 */
  --bubble-me-font-size: 13px;
  --bubble-them-font-size: 13px;
  --bubble-me-padding: 8px 12px;
  --bubble-them-padding: 8px 1px;
}

/* === 4. 隐藏双方头像（不占位，但原位置仍可点击触发心声） === */
.msg-avatar-them-container,
.msg-avatar-me-container { 
  display: none !important; 
}

/* === 5. 对方气泡本体：腾出底部空间 + 设定最小宽度 === */
.bubble-them-custom {
  position: relative !important;
  background: transparent !important;
  box-shadow: none !important;
  border: none !important;
  overflow: visible !important;

  /* 给文字底部留出空白，专门放贴图 */
  padding-bottom: 30px !important; 

  /* ⚠️ 新增：强制气泡哪怕只有一个字，也要有这个保底宽度，防止贴图悬空 */
  min-width: 80px !important; 
}

/* === 6. 对方气泡底边装饰：固定大小 === */
.bubble-them-custom::after {
  content: "";
  position: absolute;
  background-image: url("https://img.heliar.top/file/1777626122355_retouch_2026050116561104.png");
  background-size: contain;      
  background-repeat: no-repeat;
  background-position: center bottom;
  pointer-events: none;
  z-index: 0;

  /* ⬇️ === 📍 调整贴图【绝对固定大小】 === ⬇️ */
  /* 不要用 100% 了，直接写死具体的 px 像素值，这样无论字多字少，贴图永远一样大 */
  width: 160px;       /* 【宽度】：建议和上面的 min-width 保持一致或稍微小一点 */
  height: 100px;      /* 【高度】：调节这里控制贴图有多高 */

  /* ⬇️ === 📍 调整贴图【上下左右位置】 === ⬇️ */
  bottom: 0px;       /* 距离底部的位置 */
  left: 0px; */
}
:root {
/* === 1. 终极顶栏：悬浮布局 + 真正的毛玻璃透视效果 === */
.chat-header-custom {
  /* 核心：让顶栏悬浮在最上层，脱离原本的排版 */
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  width: 100% !important;
  z-index: 100 !important;

  /* 真正的半透明和毛玻璃 */
  background: rgba(255, 255, 255, 0.65) !important; /* 0.65 控制透度 */
  backdrop-filter: blur(20px) saturate(180%) !important;
  -webkit-backdrop-filter: blur(20px) saturate(180%) !important;

  border-bottom: none !important;
  box-shadow: none !important;
}

/* === 2. 核心配合：让消息区域钻到顶栏底下 === */
.chat-messages-area {
  /* 由于顶栏悬浮了，这里用 padding 给顶栏留出空间，防止最新的消息被顶栏一直挡住 */
  padding-top: 80px !important; 
}
/* === 2. 灰色昵称 === */
:root {
  --chat-header-title-color: #8e8e8e;         /* 灰色字体 */
}

/* === 3. 昵称强制绝对居中 === */
/* 隐藏顶部可能遗留的头像和在线状态，防止挤占空间 */
.header-avatar-container,
.chat-header-subtitle {
  display: none !important;
}

.chat-header-title {
  position: absolute !important;
  left: 50% !important;
  top: 50% !important;
  transform: translate(-50%, -50%) !important; /* 保证水平垂直绝对居中 */
  width: auto !important;
  text-align: center !important;
}

/* === 4. 隐藏电话和视频按键，但保留点击触控区 === */
.header-btn-phone svg,
.header-btn-video svg {
  opacity: 0 !important; /* 图标变透明看不见，但原本的按钮还在，不会影响点击 */
}

/* === 5. 替换返回按钮贴图 === */
.header-btn-back svg {
  display: none !important; /* 隐藏官方箭头 */
}
.header-btn-back {
  background-image: url("https://img.heliar.top/file/1777627271305_retouch_2026050117181605.png") !important;
  background-size: contain !important; /* contain：完整显示不裁剪 */
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-color: transparent !important;

  /* 给贴图自身加上悬浮阴影（不是按钮方框的阴影，而是顺着图案轮廓的阴影） */
  filter: drop-shadow(0px 4px 6px rgba(0, 0, 0, 0.15)) !important;

  /* ⬇️ === 📍 调整【返回贴图】大小 === ⬇️ */
  width: 35px !important;  
  height: 35px !important; 

  /* ⬇️ === 📍 调整【返回贴图】上下左右位置 === ⬇️ */
  /* 第1个值调左右(负数向左)，第2个值调上下(正数向下，负数向上) */
  transform: translate(0px, 0px) !important; 
}

/* === 6. 替换设置按钮贴图 === */
.header-btn-info svg {
  display: none !important; /* 隐藏官方齿轮图标 */
}
.header-btn-info {
  background-image: url("https://img.heliar.top/file/1777627356865_retouch_2026050117185417.png") !important;
  background-size: contain !important; 
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-color: transparent !important;

  /* 给贴图自身加上悬浮阴影 */
  filter: drop-shadow(0px 4px 6px rgba(0, 0, 0, 0.15)) !important;

  /* ⬇️ === 📍 调整【设置贴图】大小 === ⬇️ */
  width: 80px !important;  
  height: 35px !important; 

  /* ⬇️ === 📍 调整【设置贴图】上下左右位置 === ⬇️ */
  /* 第1个值调左右(负数向左，正数向右)，第2个值调上下(正数向下，负数向上) */
  transform: translate(0px, 0px) !important; 
}

/* === 1. 彻底清空底栏原本的外壳与背景 === */
:root {
  --input-area-bg: transparent;
  --input-area-border-top: transparent;
  --input-area-blur: 0px;
}

.input-area-custom {
  background: transparent !important;
  border-top: none !important;
  box-shadow: none !important;
  backdrop-filter: none !important;

  /* ⬇️ === 📍 核心：调整整个胶囊的【上下左右悬浮位置】 === ⬇️ */
  padding-bottom: 20px !important; /* 【离底部的距离】：越大胶囊越往上飘 */
  padding-left: 30px !important;   /* 【左边距】：控制胶囊离屏幕左侧多远 */
  padding-right: 30px !important;  /* 【右边距】：控制胶囊离屏幕右侧多远 */
  padding-top: 10px !important;    /* 距离上方聊天气泡的间距 */
}

/* === 2. 制作悬浮“大胶囊”（让加号完美包在左侧里面） === */
.input-row-wrapper {
  background: #ffffff !important;  /* 胶囊背景色（如果需要深色模式可改 #2c2c2e） */
  border-radius: 30px !important;  /* 完美的半圆胶囊弧度 */
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.08) !important; /* 悬浮阴影 */
  display: flex !important;
  align-items: center !important;

  /* ⬇️ === 📍 调整胶囊的【胖瘦】（内边距） === ⬇️ */
  padding: 3px 6px !important;     /* 缩小内边距，让外壳更紧凑 */
}

/* 取消输入框原本的自带背景，融入我们上面的大胶囊里 */
.input-action-bar-custom {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}

/* === 3. 缩小输入框的文字与高度 === */
.input-box-custom {
  /* ⬇️ === 📍 调整输入框的【高度和文字大小】 === ⬇️ */
  font-size: 13px !important;       /* 【字号】：默认约15px，改小至13px */
  min-height: 20px !important;      /* 【高度】：控制输入框的最小高度，数值越小越扁 */

  padding-top: 6px !important;      /* 文字离上边缘距离 */
  padding-bottom: 6px !important;   /* 文字离下边缘距离 */
  padding-left: 10px !important;    /* 文字离左侧加号的距离 */
}

/* === 4. 替换贴图变量与发送键颜色 === */
:root {
  /* 替换加号 */
  --plus-btn-icon: url('https://img.heliar.top/file/1777627354934_retouch_2026050117192723.png');
  /* 替换表情/贴纸键 */
  --sticker-btn-icon: url('https://img.heliar.top/file/1777628794807_retouch_2026050117204727.png');
  /* 替换 AI 键 */
  --ai-btn-icon: url('https://img.heliar.top/file/1777627358745_retouch_2026050117202416.png');

  /* 发送键改为黑色（仅影响图标本身，无底圈） */
  --send-btn-color: #000000; 
}

/* === 5. 等比例缩小所有自定义按钮 === */
/* 强杀内置的自带 SVG 图标，防止与贴图重叠 */
.input-btn-plus svg, 
.input-btn-sticker svg, 
.input-btn-ai svg {
  display: none !important; 
}

/* 规范所有贴图按钮的大小，保持小巧精致 */
.input-btn-plus, 
.input-btn-sticker, 
.input-btn-ai {
  background-repeat: no-repeat !important;
  background-position: center !important;

  /* ⬇️ === 📍 调整按钮贴图的【大小】 === ⬇️ */
  background-size: 15px 15px !important; /* 图标实际显示的尺寸，越小越精致 */
  width: 26px !important;                /* 按钮占用的点击宽度 */
  height: 26px !important;               /* 按钮占用的点击高度 */
}

/* 缩小发送按钮 */
.send-btn-custom {
  width: 26px !important;
  height: 26px !important;
  background-color: transparent !important; /* 清除可能自带的背景色块 */
  box-shadow: none !important;
}
.send-btn-custom svg {
  width: 18px !important;
  height: 18px !important;
}

/* === 6. 隐藏语音按钮（不可见但原位置依然可点） === */
.input-btn-mic svg, 
.input-btn-mic img {
  opacity: 0 !important; 
}
/* =========================================
   特殊消息（图片/视频/卡片等）自动隐藏装饰
========================================= */

/* 当气泡内包含图片、视频、图片容器、转账卡片、位置卡片、长图卡片、礼物盒时，隐藏所有装饰 */
.bubble-me-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container)::before,
.bubble-me-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container)::after,
.bubble-them-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container)::before,
.bubble-them-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container)::after {
  display: none !important;
}

/* ================================================
 * 消息间距微调
 * ================================================ */

.chat-message-list-custom .msg-bubble-container {
  margin-bottom: 1px !important;
}

.bubble-me-custom.first,
.bubble-them-custom.first {
  margin-top: 5px;
}
/* 当气泡内包含：图片(含表情包)、视频、图片容器、转账卡片、位置卡片、长图卡片、礼物盒 时，强制背景透明并去掉内边距 */
.bubble-me-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container),
.bubble-them-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container) {
  background-color: transparent !important;
  background: transparent !important;
  padding: 0 !important;
  border: none !important;
  box-shadow: none !important;
}
/* 当气泡内包含图片、视频、转账卡片、位置卡片、长图卡片、礼物盒、电话卡片时，隐藏装饰贴图（::before 和 ::after） */
.bubble-me-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container, .msg-phone-card, [class*="call"], [class*="phone"])::before,
.bubble-me-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container, .msg-phone-card, [class*="call"], [class*="phone"])::after,
.bubble-them-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container, .msg-phone-card, [class*="call"], [class*="phone"])::before,
.bubble-them-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container, .msg-phone-card, [class*="call"], [class*="phone"])::after {
  display: none !important;
}
/* 隐藏原生占位符 */
.input-box-custom::placeholder {
    color: transparent !important;
    -webkit-text-fill-color: transparent !important;
    opacity: 0 !important;
}

/* 父容器相对定位 */
.input-action-bar-custom {
    position: relative !important;
}

/* 自定义占位符 - 只在输入框为空时显示 */
.input-action-bar-custom:has(.input-box-custom:placeholder-shown)::before {
    content: '发送消息中..' !important;
    position: absolute !important;
    left: 18px !important;        /* 根据您的加号按钮位置调整 */
    top: 50% !important;
    transform: translateY(-50%) !important;
    color: #8e8e8e !important;
    font-size: 14px !important;
    pointer-events: none !important;
    white-space: nowrap !important;
    z-index: 5 !important;
}

/* 输入框有焦点或内容时隐藏 */
.input-action-bar-custom:focus-within::before {
    display: none !important;
}

