    --bubble-me-padding: 8px 12px;
    --bubble-me-radius: 8px;
    --bubble-me-radius-first: 8px 8px 3px 8px;
    --bubble-me-radius-mid: 8px 3px 3px 8px;
    --bubble-me-radius-last: 8px 3px 8px 8px;
    --bubble-me-shadow: 0 1px 2px rgba(0, 0, 0, 0.05);
    --bubble-me-border: none;
    --bubble-me-link-color: #C92A2A;
    /* === 对方气泡 (白色) === */
    --bubble-them-bg: #ffffff;
    --bubble-them-color: #111111;
    --bubble-them-font-size: 14px;
    --bubble-them-line-height: 1.45;
    --bubble-them-padding: 8px 12px;
    --bubble-them-radius: 8px;
    --bubble-them-radius-first: 8px 8px 8px 3px;
    --bubble-them-radius-mid: 3px 8px 8px 3px;
    --bubble-them-radius-last: 3px 8px 8px 8px;
    --bubble-them-shadow: 0 1px 2px rgba(0, 0, 0, 0.05);
    --bubble-them-border: none;
    --bubble-them-link-color: #FDB2C7;
    /* === 时间戳与日期 === */
    --timestamp-color: rgba(100, 100, 100, 0.7);
    --timestamp-size: 10px;
    --timestamp-weight: 400;
    --timestamp-margin: 6px 0 14px;
    --date-divider-bg: rgba(0, 0, 0, 0.06);
    --date-divider-color: #888888;
    --date-divider-size: 11px;
    --date-divider-weight: 500;
    --date-divider-padding: 4px 12px;
    --date-divider-radius: 100px;
    /* === 输入区域 (白色) === */
    --input-area-bg: #ffffff;
    --input-area-bg-image: none;
    --input-area-bg-size: cover;
    --input-area-bg-position: center;
    --input-area-blur: 0px;
    --input-area-border-top: 1px solid #efefef;
    --input-area-padding: 10px 12px;
    --input-area-min-height: 52px;
    /* === 输入框 === */
    --input-box-bg: #f5f5f5;
    --input-box-color: #111111;
    --input-box-placeholder: #b0b0b0;
    --input-box-radius: 22px;
    --input-box-padding: 8px 16px;
    --input-box-font-size: 14px;
    --input-box-border: none;
    --input-caret-color: #FDB2C7;
    /* === 输入区按钮颜色 === */
    --plus-btn-color: #555555;
    --input-btn-color: #555555;
    --send-btn-color: #FDB2C7;
    --send-btn-bg: transparent;
}
/* ================================================
   我方气泡小三角（右下角 · #FDB2C7）
   ================================================ */
.bubble-me-custom {
    position: relative !important;
    overflow: visible !important;
}
.bubble-me-custom::after {
    content: "";
    position: absolute;
    width: 8px;
    height: 8px;
    bottom: 11px;
    right: -3px;
    background-color: #FDB2C7;
    transform: rotate(45deg);
    border-radius: 2px;
    z-index: 1;
    pointer-events: none;
}
.bubble-me-custom.mid::after,
.bubble-me-custom.first::after {
    display: none !important;
}
.bubble-me-custom.last::after,
.bubble-me-custom.single::after {
    display: block !important;
}
/* ================================================
   对方气泡小三角（左下角 · 白色）
   ================================================ */
.bubble-them-custom {
    position: relative !important;
    overflow: visible !important;
}
.bubble-them-custom::before {
    content: "";
    position: absolute;
    width: 8px;
    height: 8px;
    bottom: 10px;
    left: -4px;
    background-color: #ffffff;
    transform: rotate(45deg);
    border-radius: 2px;
    z-index: 1;
    pointer-events: none;
}
.bubble-them-custom.mid::before,
.bubble-them-custom.last::before {
    display: none !important;
}
.bubble-them-custom.first::before,
.bubble-them-custom.single::before {
    display: block !important;
}
